'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import axios from 'axios';
import { usStaySchema, type UsStayFormData } from '@/app/lib/validations/application';
import { API_BASE_URL } from '@/app/lib/constants/api';
import Input from '@/app/components/ui/Input';
import Select from '@/app/components/ui/Select';
import Button from '@/app/components/ui/Button';
import { LoadingSpinner } from '@/app/components/ui/Loader';

const US_STATES = [
  'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA',
  'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD',
  'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ',
  'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC',
  'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY'
];

export default function UsStayPage({ params }: { params: { id: string } }) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<UsStayFormData>({
    resolver: zodResolver(usStaySchema),
  });

  useEffect(() => {
    fetchApplicationData();
  }, [params.id]);

  const fetchApplicationData = async () => {
    try {
      const token = localStorage.getItem('access_token');
      const { data } = await axios.get(`${API_BASE_URL}/applications/${params.id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (data.usStayAddressLine1) {
        setValue('usStayAddressLine1', data.usStayAddressLine1);
        setValue('usStayAddressLine2', data.usStayAddressLine2 || '');
        setValue('usStayCity', data.usStayCity);
        setValue('usStayState', data.usStayState);
        setValue('usStayZipCode', data.usStayZipCode);
      }
    } catch (error) {
      console.error('Failed to fetch application:', error);
    } finally {
      setLoading(false);
    }
  };

  const onSubmit = async (data: UsStayFormData) => {
    setSubmitting(true);
    try {
      const token = localStorage.getItem('access_token');
      await axios.put(
        `${API_BASE_URL}/applications/${params.id}/us-stay`,
        data,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      router.push(`/application/${params.id}/travel-details`);
    } catch (error: any) {
      console.error('Submission error:', error);
      alert(error.response?.data?.message || 'Failed to save. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <LoadingSpinner />
      </div>
    );
  }

  return (
    <div>
      <div className="mb-8">
        <h1 className="text-2xl md:text-3xl font-bold text-gray-900 mb-2">
          U.S. Stay Address
        </h1>
        <p className="text-gray-600">
          Where will you be staying during your visit to the United States?
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="bg-white rounded-lg border border-gray-200 p-6 space-y-6">
          <Input
            label="Address Line 1"
            placeholder="Street address"
            error={errors.usStayAddressLine1?.message}
            required
            {...register('usStayAddressLine1')}
          />

          <Input
            label="Address Line 2"
            placeholder="Apt, suite, unit, etc. (optional)"
            error={errors.usStayAddressLine2?.message}
            {...register('usStayAddressLine2')}
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="City"
              placeholder="City"
              error={errors.usStayCity?.message}
              required
              {...register('usStayCity')}
            />

            <Select
              label="State"
              error={errors.usStayState?.message}
              required
              {...register('usStayState')}
            >
              <option value="">Select state</option>
              {US_STATES.map((state) => (
                <option key={state} value={state}>
                  {state}
                </option>
              ))}
            </Select>
          </div>

          <Input
            label="ZIP Code"
            placeholder="12345 or 12345-6789"
            error={errors.usStayZipCode?.message}
            required
            {...register('usStayZipCode')}
          />
        </div>

        <div className="flex justify-between">
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Back
          </Button>
          <Button
            type="submit"
            disabled={submitting}
            className="min-w-[200px]"
          >
            {submitting ? 'Saving...' : 'Continue'}
          </Button>
        </div>
      </form>
    </div>
  );
}
